import{c as a,Q as t,j as i,m as r}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Universal and Transferable Adversarial Attacks on Aligned Language Models","description":"","frontmatter":{"url":"https://arxiv.org/abs/2307.15043","title":"Universal and Transferable Adversarial Attacks on Aligned Language Models","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2307.15043,"authors":["Andy Zou","Zifan Wang","Nicholas Carlini","Milad Nasr","J. Zico Kolter","Matt Fredrikson"],"pdf_path":"pdfs/2307.15043.pdf","published_date":"2023-01-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2023-07-27-universal-adversarial-attacks-aligned-llm-2307-15043.md","filePath":"research/papers/2023-07-27-universal-adversarial-attacks-aligned-llm-2307-15043.md","lastUpdated":1785909234000}'),s={name:"research/papers/2023-07-27-universal-adversarial-attacks-aligned-llm-2307-15043.md"};function n(o,e,l,d,u,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="universal-and-transferable-adversarial-attacks-on-aligned-language-models" tabindex="-1">Universal and Transferable Adversarial Attacks on Aligned Language Models <a class="header-anchor" href="#universal-and-transferable-adversarial-attacks-on-aligned-language-models" aria-label="Permalink to &quot;Universal and Transferable Adversarial Attacks on Aligned Language Models&quot;">​</a></h1><p><strong>Authors:</strong> Andy Zou, Zifan Wang, Nicholas Carlini, Milad Nasr, J. Zico Kolter, Matt Fredrikson</p><p><strong>Year:</strong> 2023</p><p><strong>Venue:</strong> arXiv preprint (widely cited; presented at NeurIPS 2023 workshops)</p><p><strong>ArXiv:</strong> <a href="https://arxiv.org/abs/2307.15043" target="_blank" rel="noreferrer">https://arxiv.org/abs/2307.15043</a></p><p><strong>Code:</strong> <a href="https://github.com/llm-attacks/llm-attacks" target="_blank" rel="noreferrer">https://github.com/llm-attacks/llm-attacks</a></p><hr><h2 id="full-abstract" tabindex="-1">Full Abstract <a class="header-anchor" href="#full-abstract" aria-label="Permalink to &quot;Full Abstract&quot;">​</a></h2><p>Although large language models (LLMs) are trained to refuse harmful requests, we show that they remain vulnerable to adversarial attacks that automatically generate suffixes which, when appended to queries, cause aligned language models to generate objectionable behaviors. Unlike prior work relying on manual prompt engineering, we propose an automated approach that uses greedy and gradient-based search techniques to produce adversarial suffixes. A key insight is that training on multiple harmful queries and model architectures simultaneously produces attacks that are broadly effective and transfer to diverse models. Concretely, we show that suffixes generated on Vicuna-7B and Vicuna-13B transfer to GPT-3.5, GPT-4, PaLM-2, Claude, and LLaMA-2-Chat, demonstrating that white-box-optimized attacks can compromise black-box, closed-source production systems. We release code enabling the community to study adversarial robustness in LLMs and develop defenses.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>GCG (Greedy Coordinate Gradient) attack:</strong> Introduced an automated token-level optimization method that produces adversarial suffixes by combining greedy token search with gradient-guided candidate ranking — requiring no manual prompt engineering.</li><li><strong>Cross-model transferability:</strong> Demonstrated that adversarial suffixes optimized on open-source Vicuna models successfully jailbreak closed-source systems including ChatGPT (GPT-3.5 and GPT-4), Google Bard (PaLM-2), and Claude, challenging the assumption that closed APIs are robustly protected.</li><li><strong>Multi-model, multi-prompt training:</strong> Showed that optimizing a single suffix against multiple harmful queries and multiple model architectures simultaneously produces broadly effective, generalizable attacks rather than instance-specific exploits.</li><li><strong>Alignment robustness challenge:</strong> Provided compelling empirical evidence that RLHF-based alignment does not constitute robust inference-time safety — a misaligned suffix of ~20 tokens can consistently elicit harmful outputs from aligned models.</li><li><strong>Open research infrastructure:</strong> Released code and attack artifacts, seeding a large body of follow-on work on adversarial robustness, defense mechanisms, and red teaming automation.</li><li><strong>Systematic harmful behavior elicitation:</strong> Demonstrated attack effectiveness across a curated set of harmful behaviors spanning weapons, cyberattacks, and dangerous instructions — establishing a de facto evaluation protocol later formalized by HarmBench.</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>GCG operates on the token level, treating adversarial suffix generation as a discrete optimization problem. Given a harmful query and a target response prefix (e.g., &quot;Sure, here is how to...&quot;), the attack minimizes the negative log-likelihood of the target prefix by iteratively replacing suffix tokens. At each step, gradients of the loss with respect to one-hot token embeddings provide a ranked list of candidate replacements for each suffix position. A greedy beam search over these candidates selects replacements that most reduce loss, progressing token-by-token until the suffix reliably elicits the target behavior. The full optimization runs for several hundred steps and typically converges within minutes on a single GPU for 7B-parameter models.</p><p>Transferability is achieved through multi-model, multi-prompt training. Rather than optimizing a suffix for a single (query, model) pair, GCG trains on a batch of diverse harmful queries and aggregates gradients across multiple model architectures simultaneously. This forces the suffix to exploit representational features common across models rather than idiosyncratic artifacts of a single architecture, producing attacks that generalize to unseen models — including those for which no gradient access exists.</p><p>Black-box transfer evaluation appends the optimized suffix to harmful queries submitted via closed-source APIs. The key finding is that the transferred suffix retains sufficient adversarial force to overcome RLHF-trained refusal behaviors in production systems. The authors hypothesize that aligned models share a common latent geometry for refusal — and that suffixes learned to circumvent this geometry on open-source proxies carry over to closed-source systems trained on similar data distributions.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><ul><li>GCG achieves near-100% Attack Success Rate (ASR) on Vicuna-7B and Vicuna-13B across the harmful behavior benchmark with suffixes of ~20 tokens.</li><li>Transferred suffixes achieve approximately 88% ASR on GPT-3.5, ~67% on GPT-4, and measurable ASR on Claude and PaLM-2 — all models the attack was never optimized against.</li><li>Multi-model, multi-prompt training reduces ASR variance across transfer targets compared to single-model optimization.</li><li>Naive defenses (e.g., perplexity filtering) partially mitigate GCG by detecting high-perplexity suffix tokens but introduce significant false-positive rates on legitimate queries.</li><li>The attack is robust across harmful behavior categories: weapons synthesis, malware generation, social engineering, and dangerous instructions all yield high ASR.</li><li>Longer optimization budgets (more steps, larger beam widths) monotonically improve ASR up to a saturation point, with diminishing returns beyond ~500 steps.</li></ul><hr><h2 id="limitations-and-future-work" tabindex="-1">Limitations and Future Work <a class="header-anchor" href="#limitations-and-future-work" aria-label="Permalink to &quot;Limitations and Future Work&quot;">​</a></h2><ul><li><strong>Computational cost:</strong> GCG requires white-box gradient access and multiple GPU hours per suffix, limiting adversarial suffix generation to researchers with access to open-source model weights and sufficient compute.</li><li><strong>Perplexity artifacts:</strong> GCG suffixes often contain unnatural token sequences that are detectable by perplexity filters, motivating more semantically natural attack variants (e.g., AutoDAN, PAIR).</li><li><strong>Transfer reliability variance:</strong> Transfer ASR to closed-source models shows high variance across harmful behavior categories and is not fully predictable from white-box results.</li><li><strong>Adaptive defenses:</strong> Defenses specifically trained to recognize or resist GCG-style token patterns can substantially reduce ASR; the arms race between attack and defense is ongoing.</li><li><strong>Interpretability gap:</strong> It remains poorly understood why specific suffix tokens elicit harmful outputs — mechanistic interpretability of adversarial suffixes is an open research direction.</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>GCG established that RLHF alignment is not equivalent to adversarial robustness — a distinction that has profound implications for deploying LLMs in safety-critical or public-facing contexts:</p><ul><li><strong>Deployment threat model:</strong> Any publicly deployed LLM should be assumed potentially susceptible to adversarial suffix attacks, requiring defense-in-depth beyond alignment training alone.</li><li><strong>Defense prioritization:</strong> The paper motivated an entire class of defenses — input preprocessing, output monitoring, adversarial training — and demonstrated that naive heuristics (perplexity filtering) are insufficient.</li><li><strong>Red teaming automation:</strong> GCG is the foundational automated attack underpinning HarmBench and most subsequent red teaming frameworks; understanding it is prerequisite to evaluating the broader landscape.</li><li><strong>Closed-source ≠ secure:</strong> The transfer results shattered the assumption that API-only access to proprietary models provides robust safety guarantees, directly informing regulatory discussions around model release policies.</li><li><strong>Benchmark design:</strong> The multi-behavior harmful query set introduced here became an informal standard that HarmBench later formalized, making this paper foundational for safety evaluation methodology.</li></ul>',27)])])}const m=a(s,[["render",n]]);export{g as __pageData,m as default};
